package org.slavicmyths.serpenthill;
import java.util.*;
import java.nio.file.*;
import net.minecraft.core.*;
import net.minecraft.nbt.*;
import net.minecraft.world.level.block.Rotation;
public final class HillChecks {
 static int checks;static final int N=128*128*144;static void check(boolean ok,String text){checks++;if(!ok)throw new AssertionError(text);}
 static int cell(int x,int y,int z){return (x*128+z)*144+y;}
 static boolean air(String s){return s.equals("minecraft:air")||s.contains("torch");}
 static boolean walk(BitSet free,BitSet solid,int x,int y,int z){if(x<0||x>=128||z<0||z>=128||y<1||y>=143)return false;int i=cell(x,y,z);return free.get(i)&&free.get(i+1)&&solid.get(i-1);}
 public static void main(String[] args)throws Exception{
  check(HillRules.base(500,-64,320,50)==50,"invalid y fallback");check(HillRules.base(-60,-64,320,50)==-60,"valid negative foundation");check(HillRules.base(220,-64,320,300)==176,"whole height fits");check(HillRules.dangerous(90,5,85)&&!HillRules.dangerous(60,13,114)&&!HillRules.dangerous(97,81,82),"deep hazards do not cover entrances");
  for(var r:Rotation.values()){var min=new BlockPos(-200,52,300);var origin=HillGeometry.origin(min,r);var b=HillGeometry.bounds(origin,r);check(b.minX()==min.getX()&&b.minZ()==min.getZ()&&b.getXSpan()==128&&b.getZSpan()==128&&b.getYSpan()==144,"rotated unified bounds");for(int x=0;x<128;x+=7)for(int z=0;z<128;z+=7){var local=new BlockPos(x,12,z);var at=origin.offset(local.rotate(r));check(HillGeometry.local(origin,r,at).equals(local),"inverse coordinate transform");}}
  var d=new HillWorld();UUID id=UUID.randomUUID();d.ensure(id,new BlockPos(100,52,100),Rotation.NONE,195);d.enqueue(id);d.row(id).putInt("Cursor",123456);var loaded=HillWorld.load(d.save(new CompoundTag(),null),null);check(loaded.jobs().contains(id)&&loaded.row(id).getInt("Cursor")==123456,"construction resume cursor");check(loaded.near(new BlockPos(110,100,110)).contains(id),"local index reload");loaded.finish(id);check(loaded.jobs().isEmpty()&&!loaded.row(id).getBoolean("Building"),"finish is persistent");
  var p=new HillPlan(195);var free=new BitSet(N);var solid=new BitSet(N);var palette=new TreeSet<String>();long authored=0;for(int x=0;x<128;x++)for(int z=0;z<128;z++)for(int y=0;y<144;y++){String state=p.state(x,y,z);palette.add(state);int i=cell(x,y,z);if(air(state))free.set(i);else{solid.set(i);authored++;}}
  int sx=60,sy=13,sz=114;check(walk(free,solid,sx,sy,sz),"lower cave entry walkable");var visited=new BitSet(N);int[] queue=new int[N];int read=0,write=1;queue[0]=cell(sx,sy,sz);visited.set(queue[0]);while(read<write){int at=queue[read++],y=at%144,z=(at/144)%128,x=at/(144*128);for(int[] delta:new int[][]{{1,0},{-1,0},{0,1},{0,-1}})for(int dy=-1;dy<=1;dy++){int nx=x+delta[0],nz=z+delta[1],ny=y+dy;if(!walk(free,solid,nx,ny,nz))continue;int next=cell(nx,ny,nz);if(visited.get(next))continue;visited.set(next);queue[write++]=next;}}
  if(!visited.get(cell(97,81,82)))for(int[] q:new int[][]{{60,5,100},{48,5,82},{48,22,65},{67,41,65},{65,60,84},{44,81,84},{97,81,82}})System.out.println("ROUTE "+Arrays.toString(q)+" visited="+visited.get(cell(q[0],q[1],q[2]))+" voxel="+p.state(q[0],q[1],q[2])+" below="+p.state(q[0],q[1]-1,q[2]));
  check(visited.get(cell(97,81,82)),"lower and upper entrances connected");
  var reachableRooms=new com.google.gson.JsonArray();for(var room:p.rooms){boolean reached=false;for(int x=room.x0()+1;x<room.x1();x++)for(int z=room.z0()+1;z<room.z1();z++)if(visited.get(cell(x,room.floor()+1,z)))reached=true;if(room.name().equals("blocked_lair_approach")){check(reached,"blocked approach reachable up to sealed wall");check(!visited.get(cell(114,3,89)),"sealed future lair remains closed");}else check(reached,"room connected: "+room.name());reachableRooms.add(room.name());}
  net.neoforged.fml.loading.LoadingModList.of(List.of(),List.of(),List.of(),List.of(),Map.of());net.minecraft.SharedConstants.tryDetectVersion();net.minecraft.server.Bootstrap.bootStrap();for(String state:palette)if(state.startsWith("minecraft:")){String[] tokens=state.split("@");var block=net.minecraft.core.registries.BuiltInRegistries.BLOCK.getOptional(net.minecraft.resources.ResourceLocation.parse(tokens[0]));check(block.isPresent(),"native palette "+state);if(tokens.length>1)check(block.orElseThrow().getStateDefinition().getProperty("facing").getValue(tokens[1].toLowerCase()).isPresent(),"native facing "+state);}
  var out=new com.google.gson.JsonObject();out.addProperty("status","PASS");out.addProperty("checks",checks);out.addProperty("solid_voxels",authored);out.addProperty("walkable_reachable_cells",write);out.add("rooms",reachableRooms);out.add("palette",new com.google.gson.Gson().toJsonTree(palette));var surface=new com.google.gson.JsonArray();for(int x=0;x<128;x++)for(int z=0;z<128;z++){int top=143;while(top>0&&p.state(x,top,z).equals("minecraft:air"))top--;var c=new com.google.gson.JsonArray();c.add(x);c.add(top);c.add(z);c.add(p.state(x,top,z));surface.add(c);}out.add("surface",surface);var section=new com.google.gson.JsonArray();for(int x=0;x<128;x++)for(int y=0;y<144;y++){var c=new com.google.gson.JsonArray();c.add(x);c.add(y);c.add(p.state(x,y,84));section.add(c);}out.add("section_z84",section);Files.createDirectories(Path.of("docs/verification/serpent-hill-1.9.5"));Files.writeString(Path.of("docs/verification/serpent-hill-1.9.5/layout.json"),new com.google.gson.GsonBuilder().setPrettyPrinting().create().toJson(out)+"\n");
  System.out.println("HILL_OFFLINE_PASS checks="+checks+" solidVoxels="+authored+" reachable="+write+" rooms="+p.rooms.size()+"; static cell graph is not Minecraft pathfinding or a game launch");
 }
}
